UPDATE "email_templates" SET "subject" = '{employee} has submitted their SDP for your review', "body_html" = E'Hi {manager},\n\n{employee} has submitted their Self Development Plan and would like your feedback before the growth conversation.\nPlease log into the SDP tool using your domain credentials to view what they have shared and add your comments.\n\n{LINK to login}\n\nRegards,\nHuman Resources' WHERE "key" = 'AUTO_SDP_SUBMITTED' AND "scope" = 'SYSTEM_DEFAULT';
UPDATE "email_templates" SET "subject" = '{manager} has shared feedback on your SDP', "body_html" = E'Hi {employee},\n\n{manager} has shared their feedback on your Self Development Plan.\nPlease log into the SDP tool using your domain credentials to read the feedback and factor it into your growth conversation.\n\n{LINK to login}\n\nRegards,\nHuman Resources' WHERE "key" = 'AUTO_FEEDBACK_SHARED' AND "scope" = 'SYSTEM_DEFAULT';
INSERT INTO "email_templates" ("template_id", "key", "scope", "subject", "body_html", "updated_at") SELECT 'f171d9c4-9808-4c02-b0b3-4d83acbce003', 'AUTO_CHECKIN_COMPLETED', 'SYSTEM_DEFAULT', '{employee} has completed their {check_in} check-in', E'Hi {manager},\n\n{employee} has completed their {check_in} check-in on the SDP tool. Their progress notes are ready for you to review.\nPlease log into the SDP tool using your domain credentials to view the check-in and share any feedback where relevant.\n\n{LINK to login}\n\nRegards,\nHuman Resources', CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM "email_templates" WHERE "key" = 'AUTO_CHECKIN_COMPLETED' AND "scope" = 'SYSTEM_DEFAULT');
